    "advisory.e2.body": "\u6700\u8FD1\u96CC\u4E8C\u9187\u7684\u7528\u91CF\u770B\u8D77\u6765\u6709\u70B9\u9AD8\u3002\u518D\u5F80\u4E0A\u52A0\uFF0C\u6548\u679C\u4E0D\u4F1A\u66F4\u5FEB\uFF0C\u53CD\u800C\u53EF\u80FD\u589E\u52A0\u4E00\u4E9B\u8840\u6813\u65B9\u9762\u7684\u8D1F\u62C5\u3002\u8BF7\u4E0D\u8981\u7740\u6025\uFF0C\u8FD9\u53EF\u80FD\u662F\u672C\u8F6F\u4EF6\u4F30\u6D4B\u4E0D\u51C6\uFF0C\u53EF\u4EE5\u53BB\u533B\u9662\u6D4B\u4E00\u4E0B\u6FC0\u7D20\u516D\u9879\u6821\u51C6\u6570\u503C\uFF0C\u5E76\u6CE8\u610F\u6700\u8FD1\u7684\u7528\u836F\u5242\u91CF\u3002",
    "advisory.t.body": "\u6700\u8FD1\u777E\u916E\u7684\u7528\u91CF\u770B\u8D77\u6765\u6709\u70B9\u9AD8\u3002\u4E00\u76F4\u504F\u9AD8\u4E3B\u8981\u662F\u8BA9\u8840\u6DB2\u7A0D\u5FAE\u53D8\u7A20\u4E00\u4E9B\uFF0C\u5E76\u4E0D\u4F1A\u5E26\u6765\u66F4\u591A\u597D\u5904\u3002\u8BF7\u4E0D\u8981\u7740\u6025\uFF0C\u8FD9\u53EF\u80FD\u662F\u672C\u8F6F\u4EF6\u4F30\u6D4B\u4E0D\u51C6\uFF0C\u53EF\u4EE5\u53BB\u533B\u9662\u6D4B\u4E00\u4E0B\u6FC0\u7D20\u516D\u9879\u6821\u51C6\u6570\u503C\uFF0C\u5E76\u6CE8\u610F\u6700\u8FD1\u7684\u7528\u836F\u5242\u91CF\u3002",
    "advisory.cpa.body": "\u6700\u8FD1 CPA \u7684\u7528\u91CF\u770B\u8D77\u6765\u6709\u70B9\u9AD8\uFF0C\u518D\u52A0\u91CF\u5E76\u4E0D\u4F1A\u66F4\u597D\u5730\u538B\u4F4E\u777E\u916E\uFF0C\u98CE\u9669\u5374\u4F1A\u6162\u6162\u7D2F\u79EF\u3002\u8BF7\u4E0D\u8981\u7740\u6025\uFF0C\u8FD9\u53EF\u80FD\u662F\u672C\u8F6F\u4EF6\u4F30\u6D4B\u4E0D\u51C6\uFF0C\u53EF\u4EE5\u53BB\u533B\u9662\u6D4B\u4E00\u4E0B\u6FC0\u7D20\u516D\u9879\u6821\u51C6\u6570\u503C\uFF0C\u5E76\u6CE8\u610F\u6700\u8FD1\u7684\u7528\u836F\u5242\u91CF\u3002",
    "advisory.e2_cpa.body": "\u6700\u8FD1\u96CC\u4E8C\u9187\u548C CPA \u7684\u7528\u91CF\u770B\u8D77\u6765\u90FD\u6709\u70B9\u9AD8\u3002\u96CC\u4E8C\u9187\u504F\u9AD8\u4E3B\u8981\u7275\u6D89\u8840\u6813\u65B9\u9762\u7684\u98CE\u9669\uFF0CCPA \u504F\u9AD8\u7684\u98CE\u9669\u4F1A\u968F\u65F6\u95F4\u6162\u6162\u7D2F\u79EF\u3002\u8BF7\u4E0D\u8981\u7740\u6025\uFF0C\u8FD9\u53EF\u80FD\u662F\u672C\u8F6F\u4EF6\u4F30\u6D4B\u4E0D\u51C6\uFF0C\u53EF\u4EE5\u53BB\u533B\u9662\u6D4B\u4E00\u4E0B\u6FC0\u7D20\u516D\u9879\u6821\u51C6\u6570\u503C\uFF0C\u5E76\u6CE8\u610F\u6700\u8FD1\u7684\u7528\u836F\u5242\u91CF\u3002",
