    "cal.desc.mipd": "\u6A21\u578B\u6307\u5BFC\u7684\u7CBE\u51C6\u7ED9\u836F\u3002\u5728\u7FA4\u4F53\u5148\u9A8C\u4E0B\u5BF9\u5E45\u5EA6\u4E0E\u6E05\u9664\u7387\u505A MAP \u62DF\u5408\uFF0C\u91C7\u7528\u7A33\u5065\uFF08Student-t\uFF09\u4F3C\u7136\uFF1A\u6570\u636E\u7A00\u758F\u65F6\u5411\u7FA4\u4F53\u6536\u7F29\uFF0C\u5E76\u80FD\u62B5\u5FA1\u5355\u4E2A\u5F02\u5E38\u503C\u3002",
