    "onboarding.start": "Get started",
    "onboarding.welcome_title": "Hello there",
    "onboarding.welcome_subtitle": "This app keeps track of your HRT doses and estimates where your hormone levels sit between blood tests. Pick a language to start.",
    "onboarding.mode_title": "What are you tracking?",
    "onboarding.mode_subtitle": "This sets which hormones the app follows. You can change it any time in Settings.",
    "onboarding.mode_transfem_desc": "Estradiol, plus CPA or another anti-androgen.",
    "onboarding.mode_transmasc_desc": "Testosterone.",
    "onboarding.how_title": "How it works",
    "onboarding.how_subtitle": "Three steps, and the third is the one that makes the estimate yours.",
    "onboarding.how_log": "Log every dose",
    "onboarding.how_log_desc": "Route, ester, amount and time. The estimate is only ever as good as what gets recorded.",
    "onboarding.how_chart": "Watch the curve",
    "onboarding.how_chart_desc": "A pharmacokinetic model turns those doses into an estimated blood level over time.",
    "onboarding.how_calibrate": "Add blood test results",
    "onboarding.how_calibrate_desc": "Real measurements pull the model onto your own metabolism. Without them the curve is a population average.",
    "onboarding.how_chart_caption": "An example, not your own data. Days along the bottom, estimated level up the side.",
    "onboarding.how_chart_legend_model": "population model",
    "onboarding.how_chart_legend_labs": "after blood tests",
    "onboarding.how_note": "Everything here is a model estimate, not a measurement. Treat it as a rough guide and let your blood tests have the final word.",
    "onboarding.how_replay": "Replay",
    "onboarding.mcp_title": "For your AI assistant",
    "onboarding.mcp_subtitle": "Kira Tracker can hand your records to an AI assistant over MCP \u2014 no manual file export.",
    "onboarding.mcp_unlock": "Your data stays locked",
    "onboarding.mcp_unlock_desc": "The server stores no key of yours. An assistant can read your records only while you have unlocked them in the web app.",
    "onboarding.mcp_confirm": "You confirm every write",
    "onboarding.mcp_confirm_desc": "Before an assistant adds or changes anything, it shows you what it will write.",
    "onboarding.mcp_more": "The full setup lives under Settings \u2192 About.",
    "onboarding.privacy_title": "Your data, and one warning",
    "mcp.title": "Connect an AI assistant",
    "mcp.row_desc": "Let an assistant read your records over MCP",
    "mcp.intro": "Kira Tracker exposes an MCP endpoint. Any AI client that speaks Streamable HTTP \u2014 Claude Desktop, Cursor, and others \u2014 can read your data. Three steps.",
