  "dose.guide.cpa_hint.combo": "\u8207\u96CC\u6FC0\u7D20\u5408\u7528\u6642\uFF0C10 mg/\u5929\u5DF2\u53EF\u6700\u5927\u7A0B\u5EA6\u6291\u5236\u776A\u56FA\u916E",
