  "inj.guide.title": "\u4F7F\u7528\u65B9\u5F0F\u8207\u7528\u91CF",
  "inj.guide.safety": "\u4E73\u817A\u764C\u9AD8\u98A8\u96AA\u8005\u3001\u91CD\u5EA6\u809D\u969C\u7919\u60A3\u8005\u8ACB\u52FF\u4F7F\u7528\uFF01",
  "inj.guide.route_methods": "\u4F7F\u7528\u65B9\u5F0F\uFF1A\u808C\u8089\u6CE8\u5C04\u3001\u76AE\u4E0B\u6CE8\u5C04",
  "inj.guide.route_warn": "\u4E0D\u6703\u6253\u91DD\u5C31\u4E0D\u8981\u778E\u6253\uFF01",
  "inj.guide.dosage_title": "\u4F7F\u7528\u5291\u91CF\uFF1A",
  "inj.guide.dosage_ev": "\u620A\u9178\u96CC\u4E8C\u9187\uFF1A\u6BCF 5\u20137 \u5929 5 mg / \u6BCF 1\u20132 \u9031 10 mg",
  "inj.guide.dosage_ec": "\u74B0\u620A\u4E19\u9178\u96CC\u4E8C\u9187\uFF1A\u6BCF 7 \u5929 5\u20136 mg / \u6BCF 14 \u5929 10\u201312 mg",
  "inj.guide.sim_link": "\u96CC\u4E8C\u9187\u6CE8\u5C04\u5291\u6A21\u64EC\u8A08\u7B97\u5668\uFF08\u82F1\u6587\uFF09",
  "inj.guide.notes_title": "\u6CE8\u610F\u4E8B\u9805\uFF1A",
  "inj.guide.note_1": "\u8ACB\u4EE5\u6B63\u78BA\u7684\u65B9\u5F0F\u6253\u958B\u5B89\u74FF\u74F6\uFF0C\u4EE5\u907F\u514D\u88AB\u73BB\u7483\u5283\u50B7 / \u4F7F\u74F6\u5B50\u788E\u88C2 / \u4F7F\u5FAE\u5C0F\u7684\u73BB\u7483\u788E\u6E23\u6DF7\u5165\u85E5\u6C34\u3002",
  "inj.guide.note_2": "\u8ACB\u52FF\u91CD\u8907\u6CE8\u5165\u540C\u4E00\u4F4D\u7F6E\u3002",
  "inj.guide.note_3": "\u5C0F\u5FC3\u907F\u958B\u8840\u7BA1\u3002\u53EF\u80FD\u6813\u585E\u8840\u7BA1\uFF01",
  "inj.guide.note_4": "\u5C0F\u5FC3\u907F\u958B\u795E\u7D93\u3002\u82E5\u9032\u884C\u808C\u8089\u6CE8\u5C04\uFF0C\u5728\u5B89\u5168\u5340\u57DF\u5167\u6CE8\u5C04\u3002",
  "inj.guide.note_5": "\u7531\u65BC\u85E5\u54C1\u70BA\u6CB9\u6027\uFF0C\u5EFA\u8B70\u4F7F\u7528 12 \u865F\u91DD\u982D\uFF08\u7C89\uFF0C18G\uFF09\u62BD\u53D6\u85E5\u54C1\uFF0C6 \u865F\u91DD\u982D\uFF08\u85CD\uFF0C23G / 25G\uFF09\u6CE8\u5C04\u3002",
  "inj.guide.note_6": "\u5FEB\u901F\u9032\u91DD\u548C\u62BD\u85E5\u5B8C\u7562\u5F8C\u4F7F\u7528\u65B0\u7684\u91DD\u982D\u6CE8\u5C04\u6709\u52A9\u65BC\u7DE9\u89E3\u75BC\u75DB\u3002",
  "inj.guide.note_7": "\u81EA\u884C\u6CE8\u5C04\u5EFA\u8B70\u4F7F\u7528\u80A1\u5916\u5074\u808C\uFF08\u5927\u817F\u4E09\u5206\u4E4B\u4E00\u4E2D\u6BB5\u659C\u5916\u4E0A\u65B9\uFF09\u548C\u4E09\u89D2\u808C\uFF08\u6253\u75AB\u82D7\u7684\u4F4D\u7F6E\uFF09\u3002",
  "inj.guide.note_8": "\u5982\u679C\u60A8\u5728\u63D2\u5165\u6CE8\u5C04\u91DD\u982D\u6642\u611F\u5230\u5287\u70C8\u75BC\u75DB\u6216\u770B\u5230\u5927\u91CF\u8840\u6DB2\u56DE\u6D41\uFF0C\u8ACB\u7ACB\u5373\u62D4\u51FA\u91DD\u982D\uFF0C\u66F4\u63DB\u65B0\u7684\u91DD\u982D\u4E26\u66F4\u63DB\u6CE8\u5C04\u90E8\u4F4D\u3002",
  "inj.guide.note_9": "\u5982\u679C\u5728\u67D0\u6B21\u6CE8\u5C04\u7D50\u675F\u5F8C\u6709\u8F03\u4EE5\u5F80\u66F4\u591A\u51FA\u8840\uFF08\u4F46\u53EF\u4EE5\u6B62\u4F4F\uFF09\uFF0C\u5C6C\u65BC\u6B63\u5E38\u73FE\u8C61\uFF0C\u8ACB\u4E0D\u8981\u9A5A\u614C\u3002",
