  "disclaimer.text.intro": "Kira Tracker \u4E0D\u63D0\u4F9B\u91AB\u5B78\u5EFA\u8B70\u3002\u5118\u7BA1 Kira Tracker \u5305\u542B\u4E00\u4E9B\u91AB\u5B78\u76F8\u95DC\u5167\u5BB9\uFF0C\u4F46\u4E0D\u4FDD\u8B49\u5176\u6E96\u78BA\u6027\u6216\u6642\u6548\u6027\u3002\u53EF\u80FD\u7121\u6CD5\u5B8C\u5168\u9069\u7528\u65BC\u60A8\u7684\u5177\u9AD4\u60C5\u6CC1\u3002\u8ACB\u6CE8\u610F\u4EE5\u4E0B\u4E8B\u9805\uFF1A",
