  "disclaimer.text.point3": "\u82E5\u6709\u4EFB\u4F55\u5065\u5EB7\u7591\u616E\uFF0C\u8ACB\u8AEE\u8A62\u5177\u5099\u8CC7\u8CEA\u7684\u91AB\u52D9\u4EBA\u54E1\u3002",
