    "advisory.e2.body": "\u6700\u8FD1\u96CC\u4E8C\u9187\u7684\u7528\u91CF\u770B\u8D77\u4F86\u6709\u9EDE\u9AD8\u3002\u518D\u5F80\u4E0A\u52A0\uFF0C\u6548\u679C\u4E0D\u6703\u66F4\u5FEB\uFF0C\u53CD\u800C\u53EF\u80FD\u589E\u52A0\u4E00\u4E9B\u8840\u6813\u65B9\u9762\u7684\u8CA0\u64D4\u3002\u8ACB\u4E0D\u8981\u8457\u6025\uFF0C\u9019\u53EF\u80FD\u662F\u672C\u8EDF\u4EF6\u4F30\u6E2C\u4E0D\u6E96\uFF0C\u53EF\u4EE5\u53BB\u91AB\u9662\u6E2C\u4E00\u4E0B\u6FC0\u7D20\u516D\u9805\u6821\u6E96\u6578\u503C\uFF0C\u4E26\u6CE8\u610F\u6700\u8FD1\u7684\u7528\u85E5\u5291\u91CF\u3002",
    "advisory.t.body": "\u6700\u8FD1\u777E\u916E\u7684\u7528\u91CF\u770B\u8D77\u4F86\u6709\u9EDE\u9AD8\u3002\u4E00\u76F4\u504F\u9AD8\u4E3B\u8981\u662F\u8B93\u8840\u6DB2\u7A0D\u5FAE\u8B8A\u7A20\u4E00\u4E9B\uFF0C\u4E26\u4E0D\u6703\u5E36\u4F86\u66F4\u591A\u597D\u8655\u3002\u8ACB\u4E0D\u8981\u8457\u6025\uFF0C\u9019\u53EF\u80FD\u662F\u672C\u8EDF\u4EF6\u4F30\u6E2C\u4E0D\u6E96\uFF0C\u53EF\u4EE5\u53BB\u91AB\u9662\u6E2C\u4E00\u4E0B\u6FC0\u7D20\u516D\u9805\u6821\u6E96\u6578\u503C\uFF0C\u4E26\u6CE8\u610F\u6700\u8FD1\u7684\u7528\u85E5\u5291\u91CF\u3002",
