    "inj.guide.notes_title": "\u6CE8\u610F\u4E8B\u9805\uFF1A",
    "inj.guide.note_1": "\u7528\u5571\u5605\u65B9\u6CD5\u958B\u5B89\u74FF\u74F6\uFF0C\u907F\u514D\u4FFE\u73BB\u7483\u5272\u50B7 / \u6574\u788E\u74F6 / \u7D30\u788E\u73BB\u7483\u6E23\u6DF7\u5165\u85E5\u6C34\u3002",
    "inj.guide.note_2": "\u5514\u597D\u91CD\u8907\u6253\u540C\u4E00\u500B\u4F4D\u3002",
    "inj.guide.note_3": "\u5C0F\u5FC3\u907F\u958B\u8840\u7BA1\u3002\u53EF\u80FD\u6813\u585E\u8840\u7BA1\uFF01",
    "inj.guide.note_4": "\u5C0F\u5FC3\u907F\u958B\u795E\u7D93\u3002\u505A\u808C\u8089\u6CE8\u5C04\u5605\u8A71\uFF0C\u8981\u55BA\u5B89\u5168\u5340\u57DF\u5165\u9762\u6CE8\u5C04\u3002",
    "inj.guide.note_5": "\u56E0\u70BA\u85E5\u54C1\u4FC2\u6CB9\u6027\uFF0C\u5EFA\u8B70\u7528 12 \u865F\u91DD\u982D\uFF08\u7C89\u7D05\uFF0C18G\uFF09\u62BD\u85E5\uFF0C6 \u865F\u91DD\u982D\uFF08\u85CD\uFF0C23G / 25G\uFF09\u6CE8\u5C04\u3002",
    "inj.guide.note_6": "\u5FEB\u901F\u9032\u91DD\u540C\u62BD\u5B8C\u85E5\u4E4B\u5F8C\u63DB\u65B0\u91DD\u982D\u6CE8\u5C04\u6709\u52A9\u6E1B\u5C11\u75DB\u695A\u3002",
    "inj.guide.note_7": "\u81EA\u5DF1\u6253\u91DD\u5EFA\u8B70\u7528\u80A1\u5916\u5074\u808C\uFF08\u5927\u9AC0\u4E09\u5206\u4E00\u4E2D\u6BB5\u659C\u5916\u4E0A\u65B9\uFF09\u540C\u4E09\u89D2\u808C\uFF08\u6253\u75AB\u82D7\u5605\u4F4D\u7F6E\uFF09\u3002",
    "inj.guide.note_8": "\u5982\u679C\u63D2\u5165\u91DD\u982D\u6642\u611F\u5230\u5287\u75DB\u6216\u8005\u898B\u5230\u5927\u91CF\u8840\u6DB2\u56DE\u6D41\uFF0C\u5373\u523B\u62D4\u51FA\u91DD\u982D\uFF0C\u63DB\u65B0\u91DD\u982D\u540C\u66F4\u63DB\u6CE8\u5C04\u4F4D\u7F6E\u3002",
