    "mcp.intro": "Kira \u8A18\u9304\u63D0\u4F9B\u7B26\u5408 MCP \u898F\u7BC4\u5605\u4ECB\u9762\u3002\u4EFB\u4F55\u652F\u63F4 Streamable HTTP \u5605 AI \u5BA2\u6236\u7AEF\u2014\u2014Claude Desktop\u3001Cursor \u7B49\u2014\u2014\u90FD\u8B80\u5F97\u5230\u4F60\u5605\u8CC7\u6599\u3002\u4E09\u6B65\u641E\u6382\u3002",
