    "inj.guide.route_warn": "\u6CE8\u5C04\u306E\u8A13\u7DF4\u3092\u53D7\u3051\u3066\u3044\u306A\u3044\u5834\u5408\u306F\u884C\u308F\u306A\u3044\u3067\u304F\u3060\u3055\u3044\uFF01",
