    "inj.guide.dosage_ev": "\u5409\u8349\u9178\u30A8\u30B9\u30C8\u30E9\u30B8\u30AA\u30FC\u30EB\uFF1A5\u20137\u65E5\u3054\u3068\u306B 5 mg / 1\u20132\u9031\u3054\u3068\u306B 10 mg",
    "inj.guide.dosage_ec": "\u30B7\u30D4\u30AA\u30F3\u9178\u30A8\u30B9\u30C8\u30E9\u30B8\u30AA\u30FC\u30EB\uFF1A7\u65E5\u3054\u3068\u306B 5\u20136 mg / 14\u65E5\u3054\u3068\u306B 10\u201312 mg",
    "inj.guide.sim_link": "E2\u6CE8\u5C04\u30B7\u30DF\u30E5\u30EC\u30FC\u30BF\u30FC\uFF08\u82F1\u8A9E\uFF09",
    "inj.guide.notes_title": "\u6CE8\u610F\u4E8B\u9805\uFF1A",
    "inj.guide.note_1": "\u30A2\u30F3\u30D7\u30EB\u306F\u6B63\u3057\u3044\u65B9\u6CD5\u3067\u958B\u5C01\u3057\u3001\u30AC\u30E9\u30B9\u306B\u3088\u308B\u5207\u308A\u50B7\u30FB\u7834\u640D\u30FB\u5FAE\u7D30\u306A\u30AC\u30E9\u30B9\u7247\u306E\u6DF7\u5165\u3092\u9632\u3044\u3067\u304F\u3060\u3055\u3044\u3002",
    "inj.guide.note_2": "\u540C\u3058\u90E8\u4F4D\u306B\u7E70\u308A\u8FD4\u3057\u6CE8\u5C04\u3057\u306A\u3044\u3067\u304F\u3060\u3055\u3044\u3002",
    "inj.guide.note_3": "\u8840\u7BA1\u3092\u907F\u3051\u3066\u304F\u3060\u3055\u3044\u3002\u8840\u6813\uFF08\u585E\u6813\uFF09\u306E\u30EA\u30B9\u30AF\u304C\u3042\u308A\u307E\u3059\uFF01",
    "inj.guide.note_4": "\u795E\u7D4C\u3092\u907F\u3051\u3066\u304F\u3060\u3055\u3044\u3002\u7B4B\u8089\u6CE8\u5C04\u306E\u5834\u5408\u306F\u5B89\u5168\u306A\u90E8\u4F4D\u306B\u6CE8\u5C04\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
    "inj.guide.note_5": "\u6CB9\u6027\u85AC\u5264\u306E\u305F\u3081\u300112\u756A\u91DD\uFF08\u30D4\u30F3\u30AF\u300118G\uFF09\u3067\u5438\u5F15\u3057\u30016\u756A\u91DD\uFF08\u9752\u300123G/25G\uFF09\u3067\u6CE8\u5C04\u3059\u308B\u3053\u3068\u3092\u63A8\u5968\u3057\u307E\u3059\u3002",
    "inj.guide.note_6": "\u7D20\u65E9\u3044\u523A\u5165\u3068\u3001\u5438\u5F15\u5F8C\u306B\u65B0\u3057\u3044\u91DD\u306B\u4EA4\u63DB\u3057\u3066\u6CE8\u5C04\u3059\u308B\u3053\u3068\u3067\u75DB\u307F\u3092\u8EFD\u6E1B\u3067\u304D\u307E\u3059\u3002",
    "inj.guide.note_7": "\u81EA\u5DF1\u6CE8\u5C04\u306B\u306F\u5916\u5074\u5E83\u7B4B\uFF08\u5927\u817F\u4E2D\u592E\u5916\u5074\u4E0A\u90E8\uFF09\u307E\u305F\u306F\u4E09\u89D2\u7B4B\uFF08\u30EF\u30AF\u30C1\u30F3\u63A5\u7A2E\u90E8\u4F4D\uFF09\u3092\u63A8\u5968\u3057\u307E\u3059\u3002",
    "inj.guide.note_8": "\u91DD\u3092\u523A\u3057\u305F\u969B\u306B\u6FC0\u3057\u3044\u75DB\u307F\u3084\u5927\u91CF\u306E\u8840\u6DB2\u9006\u6D41\u304C\u3042\u308B\u5834\u5408\u306F\u3001\u76F4\u3061\u306B\u91DD\u3092\u629C\u304D\u3001\u65B0\u3057\u3044\u91DD\u306B\u4EA4\u63DB\u3057\u3066\u6CE8\u5C04\u90E8\u4F4D\u3092\u5909\u66F4\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
    "inj.guide.note_9": "\u6CE8\u5C04\u5F8C\u306B\u3044\u3064\u3082\u3088\u308A\u591A\u3044\u51FA\u8840\u304C\u3042\u3063\u3066\u3082\uFF08\u6B62\u8840\u53EF\u80FD\u3067\u3042\u308C\u3070\uFF09\u6B63\u5E38\u3067\u3059\u3002\u614C\u3066\u306A\u3044\u3067\u304F\u3060\u3055\u3044\u3002",
