    "disclaimer.text.intro": "Kira Tracker \u306F\u533B\u5B66\u7684\u52A9\u8A00\u3092\u63D0\u4F9B\u3059\u308B\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002Kira Tracker \u306B\u306F\u533B\u5B66\u95A2\u9023\u306E\u30B3\u30F3\u30C6\u30F3\u30C4\u304C\u542B\u307E\u308C\u3066\u3044\u307E\u3059\u304C\u3001\u305D\u306E\u6B63\u78BA\u6027\u3084\u9069\u6642\u6027\u3092\u4FDD\u8A3C\u3059\u308B\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u304A\u5BA2\u69D8\u306E\u7279\u5B9A\u306E\u72B6\u6CC1\u306B\u5B8C\u5168\u306B\u9069\u7528\u3055\u308C\u306A\u3044\u5834\u5408\u304C\u3042\u308A\u307E\u3059\u3002\u4EE5\u4E0B\u306E\u70B9\u306B\u3054\u6CE8\u610F\u304F\u3060\u3055\u3044\uFF1A",
    "disclaimer.text.point1": "\u533B\u5B66\u60C5\u5831\u306F\u53C2\u8003\u7528\u3067\u3042\u308A\u3001\u8CC7\u683C\u306E\u3042\u308B\u533B\u7642\u5F93\u4E8B\u8005\u306E\u8A3A\u65AD\u3084\u6CBB\u7642\u306E\u52A9\u8A00\u306B\u4EE3\u308F\u308B\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
    "disclaimer.text.point2": "\u5185\u5BB9\u304C\u6B63\u78BA\u3067\u3042\u3063\u3066\u3082\u3001\u304A\u5BA2\u69D8\u306E\u5065\u5EB7\u72B6\u614B\u306B\u5F53\u3066\u306F\u307E\u308B\u3068\u306F\u9650\u308A\u307E\u305B\u3093\u3002",
