    "label.e2_unit": "\uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C (pg/mL)",
    "label.cpa_unit": "\uC0AC\uC774\uD504\uB85C\uD14C\uB860 \uC544\uC138\uD14C\uC774\uD2B8 (ng/mL)",
    "timeline.title": "\uBCF5\uC6A9 \uAE30\uB85D",
    "chart.title": "\uD638\uB974\uBAAC \uC218\uCE58 \uBCC0\uD654",
    "chart.reset": "\uBCF4\uAE30 \uCD08\uAE30\uD654",
    "chart.range_7d": "7\uC77C",
    "chart.range_30d": "30\uC77C",
    "chart.range_all": "\uC804\uCCB4",
    "chart.target": "\uBAA9\uD45C \uBC94\uC704",
    "heatmap.title": "\uBCF5\uC57D \uD788\uD2B8\uB9F5",
    "heatmap.summary": "\uCD5C\uADFC {d}\uC77C \xB7 {n}\uD68C \uBCF5\uC57D",
    "heatmap.summary_one": "\uCD5C\uADFC {d}\uC77C \xB7 1\uD68C \uBCF5\uC57D",
    "heatmap.doses": "{n}\uD68C \uBCF5\uC57D",
    "heatmap.dose_one": "1\uD68C \uBCF5\uC57D",
    "heatmap.none": "\uBCF5\uC57D \uC5C6\uC74C",
    "advisory.e2.body": "\uCD5C\uADFC \uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C \uC6A9\uB7C9\uC774 \uC870\uAE08 \uB9CE\uC544 \uBCF4\uC5EC\uC694. \uB354 \uB298\uB824\uB3C4 \uD6A8\uACFC\uAC00 \uBE68\uB77C\uC9C0\uC9C4 \uC54A\uACE0, \uD608\uC804 \uC704\uD5D8\uC774 \uC870\uAE08 \uC62C\uB77C\uAC08 \uC218 \uC788\uC5B4\uC694. \uB108\uBB34 \uAC71\uC815\uD558\uC9C0 \uB9C8\uC138\uC694. \uC774 \uC571\uC758 \uCD94\uC815\uCE58\uAC00 \uBD80\uC815\uD655\uD560 \uC218 \uC788\uC5B4\uC694. \uBCD1\uC6D0\uC5D0\uC11C \uD638\uB974\uBAAC \uD608\uC561 \uAC80\uC0AC\uB97C \uBC1B\uC73C\uBA74 \uC218\uCE58\uB97C \uBCF4\uC815\uD560 \uC218 \uC788\uACE0, \uCD5C\uADFC \uBCF5\uC6A9\uB7C9\uB3C4 \uD55C\uBC88 \uC0B4\uD3B4\uBD10 \uC8FC\uC138\uC694.",
    "advisory.t.body": "\uCD5C\uADFC \uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uC6A9\uB7C9\uC774 \uC870\uAE08 \uB9CE\uC544 \uBCF4\uC5EC\uC694. \uACC4\uC18D \uB192\uAC8C \uC720\uC9C0\uD574\uB3C4 \uC8FC\uB85C \uD53C\uAC00 \uC870\uAE08 \uAC78\uCB49\uD574\uC9C8 \uBFD0 \uBCC4\uB2E4\uB978 \uC774\uB4DD\uC740 \uC5C6\uC5B4\uC694. \uB108\uBB34 \uAC71\uC815\uD558\uC9C0 \uB9C8\uC138\uC694. \uC774 \uC571\uC758 \uCD94\uC815\uCE58\uAC00 \uBD80\uC815\uD655\uD560 \uC218 \uC788\uC5B4\uC694. \uBCD1\uC6D0\uC5D0\uC11C \uD638\uB974\uBAAC \uD608\uC561 \uAC80\uC0AC\uB97C \uBC1B\uC73C\uBA74 \uC218\uCE58\uB97C \uBCF4\uC815\uD560 \uC218 \uC788\uACE0, \uCD5C\uADFC \uBCF5\uC6A9\uB7C9\uB3C4 \uD55C\uBC88 \uC0B4\uD3B4\uBD10 \uC8FC\uC138\uC694.",
    "advisory.cpa.body": "\uCD5C\uADFC CPA \uC6A9\uB7C9\uC774 \uC870\uAE08 \uB9CE\uC544 \uBCF4\uC5EC\uC694. \uB298\uB824\uB3C4 \uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uC5B5\uC81C\uAC00 \uB354 \uAC15\uD574\uC9C0\uC9C4 \uC54A\uACE0, \uC704\uD5D8\uB9CC \uC11C\uC11C\uD788 \uC62C\uB77C\uAC00\uC694. \uB108\uBB34 \uAC71\uC815\uD558\uC9C0 \uB9C8\uC138\uC694. \uC774 \uC571\uC758 \uCD94\uC815\uCE58\uAC00 \uBD80\uC815\uD655\uD560 \uC218 \uC788\uC5B4\uC694. \uBCD1\uC6D0\uC5D0\uC11C \uD638\uB974\uBAAC \uD608\uC561 \uAC80\uC0AC\uB97C \uBC1B\uC73C\uBA74 \uC218\uCE58\uB97C \uBCF4\uC815\uD560 \uC218 \uC788\uACE0, \uCD5C\uADFC \uBCF5\uC6A9\uB7C9\uB3C4 \uD55C\uBC88 \uC0B4\uD3B4\uBD10 \uC8FC\uC138\uC694.",
    "advisory.e2_cpa.body": "\uCD5C\uADFC \uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C\uACFC CPA \uC6A9\uB7C9\uC774 \uB458 \uB2E4 \uC870\uAE08 \uB9CE\uC544 \uBCF4\uC5EC\uC694. \uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C\uC740 \uC8FC\uB85C \uD608\uC804 \uC704\uD5D8\uC744, CPA\uB294 \uC2DC\uAC04\uC774 \uC9C0\uB098\uBA70 \uC313\uC774\uB294 \uC704\uD5D8\uC744 \uAC01\uAC01 \uB354\uD574\uC694. \uB108\uBB34 \uAC71\uC815\uD558\uC9C0 \uB9C8\uC138\uC694. \uC774 \uC571\uC758 \uCD94\uC815\uCE58\uAC00 \uBD80\uC815\uD655\uD560 \uC218 \uC788\uC5B4\uC694. \uBCD1\uC6D0\uC5D0\uC11C \uD638\uB974\uBAAC \uD608\uC561 \uAC80\uC0AC\uB97C \uBC1B\uC73C\uBA74 \uC218\uCE58\uB97C \uBCF4\uC815\uD560 \uC218 \uC788\uACE0, \uCD5C\uADFC \uBCF5\uC6A9\uB7C9\uB3C4 \uD55C\uBC88 \uC0B4\uD3B4\uBD10 \uC8FC\uC138\uC694.",
    "advisory.calibrate.text": "\uC774\uAC74 \uBAA8\uB378 \uCD94\uC815\uCE58\uC608\uC694.",
    "advisory.calibrate.cta": "\uD608\uC561 \uAC80\uC0AC \uACB0\uACFC\uB97C \uCD94\uAC00\uD574 \uBCF4\uC815\uD558\uAE30",
    "advisory.hormone_both_low.body": "\uCD5C\uADFC \uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C\uACFC \uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uC218\uCE58\uAC00 \uB458 \uB2E4 \uB0AE\uAC8C \uB098\uC654\uC5B4\uC694. \uB450 \uC131\uD638\uB974\uBAAC\uC774 \uB3D9\uC2DC\uC5D0 \uB0AE\uC73C\uBA74 \uC7A5\uAE30\uC801\uC73C\uB85C \uACE8\uBC00\uB3C4, \uAE30\uBD84, \uC548\uBA74\uD64D\uC870 \uAC19\uC740 \uD608\uAD00\uC6B4\uB3D9 \uC99D\uC0C1\uC5D0 \uC601\uD5A5\uC744 \uC904 \uC218 \uC788\uC5B4\uC694. \uCC44\uD608 \uC2DC\uC810 \uB54C\uBB38\uC77C \uC218\uB3C4 \uC788\uC73C\uB2C8 \uCD5C\uADFC \uBCF5\uC6A9\uB7C9\uACFC \uD568\uAED8 \uC758\uC0AC\uC640 \uC0C1\uC758\uD574 \uBCF4\uC138\uC694.",
    "advisory.hormone_both_high.body": "\uCD5C\uADFC \uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C\uACFC \uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uC218\uCE58\uAC00 \uB458 \uB2E4 \uB192\uAC8C \uB098\uC654\uC5B4\uC694. \uD754\uCE58 \uC54A\uC740 \uC870\uD569\uC774\uB77C \uD55C\uBC88 \uD655\uC778\uD574\uBCFC \uB9CC\uD574\uC694. \uCC44\uD608 \uC2DC\uC810\uC774\uB098 \uB2E8\uC704 \uC785\uB825 \uC2E4\uC218\uC77C \uC218\uB3C4 \uC788\uC73C\uB2C8 \uC758\uC0AC\uC640 \uAC80\uC0AC \uACB0\uACFC\uB97C \uD655\uC778\uD574 \uBCF4\uC138\uC694.",
