    "drawer.algorithm_confirm": "\uC678\uBD80 \uC6F9\uC0AC\uC774\uD2B8(github.com)\uB97C \uBC29\uBB38\uD558\uB824\uACE0 \uD569\uB2C8\uB2E4. \uACC4\uC18D\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C?",
