    "licence.row_desc": "\uC774 \uC571\uC774 \uC0AC\uC6A9\uD558\uB294 \uC624\uD508 \uC18C\uC2A4 \uC791\uC5C5\uBB3C",
    "licence.intro": "\uC774 \uC571\uC740 \uB2E4\uB978 \uC0AC\uB78C\uB4E4\uC758 \uC791\uC5C5 \uC704\uC5D0 \uC138\uC6CC\uC838 \uC788\uC2B5\uB2C8\uB2E4. \uC0AC\uC6A9\uD558\uAC70\uB098 \uD30C\uC0DD\uD55C \uC791\uC5C5\uACFC \uAC01\uAC01\uC758 \uC870\uAC74\uC744 \uC544\uB798\uC5D0 \uBC1D\uD799\uB2C8\uB2E4.",
