    "licence.upstream_algorithm": "\uC774 \uC571\uC758 \uBAA8\uB4E0 \uC57D\uB3D9\uD559 \uACC4\uC0B0\uC5D0 \uC4F0\uC774\uB294 \uC54C\uACE0\uB9AC\uC998\uACFC \uD30C\uB77C\uBBF8\uD130\uC758 \uCD9C\uCC98.",
    "licence.upstream_original": "\uC774 \uD504\uB85C\uC81D\uD2B8\uC758 \uBFCC\uB9AC\uAC00 \uB41C \uC6F9 \uAD6C\uD604.",
    "licence.upstream_fork": "\uC774 \uC571\uC774 \uC9C1\uC811 \uD3EC\uD06C\uD55C \uD504\uB85C\uC81D\uD2B8.",
    "licence.no_licence_note": "\uC774 \uC800\uC7A5\uC18C\uB294 \uB77C\uC774\uC120\uC2A4\uB97C \uC804\uD600 \uBA85\uC2DC\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC774 \uC548\uB0B4\uC758 \uC2E4\uC218\uAC00 \uC544\uB2D9\uB2C8\uB2E4. LICENCE \uD30C\uC77C\uC774 \uC5C6\uACE0 README\uC5D0\uB3C4 \uC870\uAC74\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uACF5\uAC1C \uBC30\uD3EC \uC804\uC5D0 \uC791\uC131\uC790\uC5D0\uAC8C \uD655\uC778\uD558\uC138\uC694.",
