    "licence.deps_desc": "\uC774 \uC571\uACFC \uD568\uAED8 \uBC30\uD3EC\uB418\uB294 \uC11C\uB4DC\uD30C\uD2F0 \uB77C\uC774\uBE0C\uB7EC\uB9AC {n}\uAC1C\uC774\uBA70, \uAC01\uC790 \uC790\uC2E0\uC758 \uC870\uAC74\uC744 \uB530\uB985\uB2C8\uB2E4.",
    "licence.this_app_title": "\uC774 \uC571",
    "licence.this_app_body": "\uC774 \uC571\uC740 \uC704 MIT \uD504\uB85C\uC81D\uD2B8\uC758 \uD3EC\uD06C\uC774\uBA70, \uAC19\uC740 MIT \uB77C\uC774\uC120\uC2A4\uB85C \uBC30\uD3EC\uB429\uB2C8\uB2E4.",
