    "field.patch_wear_placeholder": "\uC608: 3.5, 7",
    "field.patch_wear_hint": "\uC120\uD0DD \uC0AC\uD56D. \uC774 \uC77C\uC218\uAC00 \uC9C0\uB098\uBA74 \uC81C\uAC70\uB41C \uAC83\uC73C\uB85C \uCC98\uB9AC\uB429\uB2C8\uB2E4. \uBE44\uC6CC \uB450\uBA74 \uC81C\uAC70\uB97C \uAE30\uB85D\uD560 \uB54C\uAE4C\uC9C0 \uBD80\uCC29 \uC0C1\uD0DC\uB85C \uC720\uC9C0\uB429\uB2C8\uB2E4.",
