    "dose.guide.title": "\uC6A9\uB7C9 \uC548\uB0B4",
    "dose.guide.current": "\uD604\uC7AC \uC785\uB825",
    "dose.guide.current_blank": "\uC548\uB0B4\uB97C \uBCF4\uB824\uBA74 \uC6A9\uB7C9\uC744 \uC785\uB825\uD558\uC138\uC694",
    "dose.guide.reference": "\uAE30\uC900 \uBC94\uC704",
    "dose.guide.patch_rate_hint": "\uD328\uCE58 \uC548\uB0B4\uB294 \uBC29\uCD9C \uC18D\uB3C4 \uAE30\uBC18\uC785\uB2C8\uB2E4. \uBCF4\uB824\uBA74 \uBC29\uCD9C \uC18D\uB3C4 \uC785\uB825\uC73C\uB85C \uC804\uD658\uD558\uC138\uC694.",
    "dose.guide.level.low": "\uB0AE\uC740 \uC6A9\uB7C9",
    "dose.guide.level.medium": "\uC911\uAC04 \uC6A9\uB7C9",
    "dose.guide.level.high": "\uB192\uC740 \uC6A9\uB7C9",
    "dose.guide.level.very_high": "\uB9E4\uC6B0 \uB192\uC740 \uC6A9\uB7C9",
    "dose.guide.level.above": "\uD45C \uBC94\uC704 \uCD08\uACFC",
    "dose.guide.unit.mg_day": "mg/\uC77C",
    "dose.guide.unit.mg_week": "mg/\uC8FC",
    "dose.guide.unit.ug_day": "\xB5g/\uC77C",
    "dose.guide.cpa_hint.rec": "\uAD8C\uC7A5 1\uC77C \uC6A9\uB7C9: 10~12.5 mg",
    "dose.guide.cpa_hint.combo": "\uC5D0\uC2A4\uD2B8\uB85C\uAC90\uACFC \uD568\uAED8 \uBCF5\uC6A9 \uC2DC 10 mg/\uC77C\uB85C \uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860\uC744 \uCD5C\uB300\uD55C \uC5B5\uC81C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4",
    "dose.guide.cpa_hint.ultralow": "\uCD08\uC800\uC6A9\uB7C9 \uBC29\uC2DD: 12.5 mg\uC744 1~3\uC77C\uB9C8\uB2E4 \uBCF5\uC6A9 (\u22483.5 mg/\uC77C \uD574\uB2F9)",
    "inj.guide.title": "\uC0AC\uC6A9\uBC95 \uBC0F \uC6A9\uB7C9",
    "inj.guide.safety": "\uC720\uBC29\uC554 \uACE0\uC704\uD5D8\uAD70, \uC911\uC99D \uAC04\uC7A5\uC560 \uD658\uC790\uB294 \uC0AC\uC6A9\uD558\uC9C0 \uB9C8\uC138\uC694!",
    "inj.guide.route_methods": "\uD22C\uC5EC \uACBD\uB85C: \uADFC\uC721 \uC8FC\uC0AC, \uD53C\uD558 \uC8FC\uC0AC",
    "inj.guide.route_warn": "\uC8FC\uC0AC \uD6C8\uB828\uC744 \uBC1B\uC9C0 \uC54A\uC558\uB2E4\uBA74 \uC2DC\uB3C4\uD558\uC9C0 \uB9C8\uC138\uC694!",
    "inj.guide.dosage_title": "\uC6A9\uB7C9:",
    "inj.guide.dosage_ev": "\uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C \uBC1C\uB808\uB808\uC774\uD2B8: 5\u20137\uC77C\uB9C8\uB2E4 5 mg / 1\u20132\uC8FC\uB9C8\uB2E4 10 mg",
    "inj.guide.dosage_ec": "\uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C \uC2DC\uD53C\uC624\uB124\uC774\uD2B8: 7\uC77C\uB9C8\uB2E4 5\u20136 mg / 14\uC77C\uB9C8\uB2E4 10\u201312 mg",
    "inj.guide.sim_link": "E2 \uC8FC\uC0AC \uC2DC\uBBAC\uB808\uC774\uD130 (\uC601\uC5B4)",
    "inj.guide.notes_title": "\uC8FC\uC758\uC0AC\uD56D:",
    "inj.guide.note_1": "\uC570\uD50C\uC740 \uC62C\uBC14\uB978 \uBC29\uBC95\uC73C\uB85C \uAC1C\uBD09\uD558\uC5EC \uC720\uB9AC \uD30C\uD3B8\uC5D0 \uC758\uD55C \uBD80\uC0C1/\uD30C\uC190/\uBBF8\uC138 \uC720\uB9AC \uC870\uAC01 \uD63C\uC785\uC744 \uBC29\uC9C0\uD558\uC138\uC694.",
    "inj.guide.note_2": "\uAC19\uC740 \uBD80\uC704\uC5D0 \uBC18\uBCF5 \uC8FC\uC0AC\uD558\uC9C0 \uB9C8\uC138\uC694.",
    "inj.guide.note_3": "\uD608\uAD00\uC744 \uD53C\uD558\uC138\uC694. \uC0C9\uC804 \uC704\uD5D8!",
    "inj.guide.note_4": "\uC2E0\uACBD\uC744 \uD53C\uD558\uC138\uC694. \uADFC\uC721 \uC8FC\uC0AC \uC2DC \uC548\uC804\uD55C \uBD80\uC704\uC5D0 \uC8FC\uC0AC\uD558\uC138\uC694.",
    "inj.guide.note_5": "\uC720\uC131 \uC57D\uBB3C\uC774\uBBC0\uB85C 12\uBC88 \uBC14\uB298(\uD551\uD06C, 18G)\uB85C \uC57D\uBB3C\uC744 \uD761\uC778\uD558\uACE0 6\uBC88 \uBC14\uB298(\uBE14\uB8E8, 23G/25G)\uB85C \uC8FC\uC0AC\uD558\uC138\uC694.",
    "inj.guide.note_6": "\uBE60\uB978 \uC0BD\uC785\uACFC \uD761\uC778 \uD6C4 \uC0C8 \uBC14\uB298\uB85C \uAD50\uCCB4\uD558\uC5EC \uC8FC\uC0AC\uD558\uBA74 \uD1B5\uC99D\uC744 \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "inj.guide.note_7": "\uC790\uAC00 \uC8FC\uC0AC \uC2DC \uC678\uCE21\uAD11\uADFC(\uB300\uD1F4 \uC911\uC559 \uC678\uCE21 \uC0C1\uBD80)\uC774\uB098 \uC0BC\uAC01\uADFC(\uBC31\uC2E0 \uC811\uC885 \uBD80\uC704)\uC744 \uC0AC\uC6A9\uD558\uC138\uC694.",
    "inj.guide.note_8": "\uBC14\uB298 \uC0BD\uC785 \uC2DC \uADF9\uC2EC\uD55C \uD1B5\uC99D\uC774\uB098 \uB2E4\uB7C9\uC758 \uD608\uC561 \uC5ED\uB958\uAC00 \uBCF4\uC774\uBA74 \uC989\uC2DC \uBC14\uB298\uC744 \uBE7C\uACE0, \uC0C8 \uBC14\uB298\uB85C \uAD50\uCCB4\uD558\uC5EC \uC8FC\uC0AC \uBD80\uC704\uB97C \uBCC0\uACBD\uD558\uC138\uC694.",
    "inj.guide.note_9": "\uC8FC\uC0AC \uD6C4 \uD3C9\uC18C\uBCF4\uB2E4 \uCD9C\uD608\uC774 \uB9CE\uC544\uB3C4(\uC9C0\uD608 \uAC00\uB2A5\uD558\uBA74) \uC815\uC0C1\uC785\uB2C8\uB2E4. \uB2F9\uD669\uD558\uC9C0 \uB9C8\uC138\uC694.",
    "inj.guide.source": "\uCD9C\uCC98: MtF.wiki",
    "sl.instructions": "\uC0BC\uD0A4\uC9C0 \uC54A\uB3C4\uB85D \uB178\uB825\uD558\uC138\uC694. \uBAA9\uD45C \uC2DC\uAC04\uAE4C\uC9C0 \uD600 \uBC11\uC5D0 \uC815\uC81C/\uD0C0\uC561\uC744 \uC720\uC9C0\uD558\uC138\uC694.",
    "sl.tier.quick": "\uBE60\uB984",
    "sl.tier.casual": "\uBCF4\uD1B5",
    "sl.tier.standard": "\uD45C\uC900",
    "sl.tier.strict": "\uC5C4\uACA9",
