    "sl.hold_time_min": "\uC720\uC9C0 \uC2DC\uAC04 (\uBD84)",
    "sl.theta_approx": "\uB300\uB7B5\uC801\uC778 \u0398",
    "sl.custom_mode": "\uC0AC\uC6A9\uC790 \uC815\uC758",
    "sl.custom_hint": "\uC720\uC9C0 \uC2DC\uAC04\uC744 \uC785\uB825\uD558\uBA74 \u03B8\uAC00 \uC790\uB3D9\uC73C\uB85C \uCD94\uC815\uB429\uB2C8\uB2E4.",
    "sl.custom_range": "\uAD8C\uC7A5 \uBC94\uC704\uB294 1-60\uBD84\uC785\uB2C8\uB2E4. \uC774 \uBC94\uC704\uB97C \uBC97\uC5B4\uB098\uBA74 \uCD94\uC815\uAC12\uC785\uB2C8\uB2E4.",
    "route.injection": "\uC8FC\uC0AC",
