    "route.sublingual": "\uC124\uD558",
    "route.gel": "\uC824",
    "gel.site.arm": "\uD314",
    "gel.site.thigh": "\uD5C8\uBC85\uC9C0",
    "gel.site.scrotal": "\uC74C\uB0AD",
    "gel.site_disabled": "\uB3C4\uD3EC \uBD80\uC704 \uC120\uD0DD\uC740 \uC544\uC9C1 \uAC1C\uBC1C \uC911\uC774\uBA70 \uC77C\uC2DC\uC801\uC73C\uB85C \uBE44\uD65C\uC131\uD654\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
    "patch.setup_hint": "\uC544\uB798\uC5D0\uC11C \uCC29\uC6A9 \uAE30\uAC04\uC744 \uC124\uC815\uD558\uAC70\uB098 \uC81C\uAC70\uB97C \uBCC4\uB3C4\uB85C \uAE30\uB85D\uD558\uC138\uC694.",
    "patch.remove_hint": "\uC81C\uAC70 \uC2DC\uAC04\uB9CC \uAE30\uB85D\uD558\uBA74 \uB429\uB2C8\uB2E4. \uC6A9\uB7C9\uC740 \uCC29\uC6A9 \uC2DC\uAC04\uC5D0\uC11C \uD30C\uC0DD\uB429\uB2C8\uB2E4.",
