    "ester.EB": "\uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C \uBCA4\uC870\uC5D0\uC774\uD2B8 (EB)",
    "ester.EC": "\uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C \uC0AC\uC774\uD53C\uC624\uB124\uC774\uD2B8 (EC)",
