    "lab.dual_hint": "\uB458 \uB2E4 \uC785\uB825\uD574\uB3C4 \uB418\uACE0 \uD558\uB098\uB9CC \uC785\uB825\uD574\uB3C4 \uB3FC\uC694. \uAC19\uC740 \uC2DC\uAC01\uC73C\uB85C \uAC01\uAC01 \uC800\uC7A5\uB3FC\uC694.",
    "lab.note": "\uBA54\uBAA8",
    "lab.calibration": "\uBAA8\uB378 \uBCF4\uC815",
    "lab.calibration_desc": "\uAC80\uC0AC \uC5D0\uC2A4\uD2B8\uB77C\uB514\uC62C \uC218\uCE58\uB97C \uC785\uB825\uD558\uC5EC \uBAA8\uB378\uC744 \uBCF4\uC815\uD569\uB2C8\uB2E4.",
    "lab.empty": "\uC544\uC9C1 \uAC80\uC0AC \uACB0\uACFC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "lab.delete_confirm": "\uC774 \uAC80\uC0AC \uACB0\uACFC\uB97C \uC0AD\uC81C\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C?",
    "lab.clear_all": "\uBCF4\uC815 \uCD08\uAE30\uD654",
    "lab.clear_confirm": "\uBAA8\uB4E0 \uBCF4\uC815 \uAE30\uB85D\uC744 \uCD08\uAE30\uD654\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C? \uC774 \uC791\uC5C5\uC740 \uCDE8\uC18C\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
