    "account.unlock_desc": "\uD074\uB77C\uC6B0\uB4DC \uBC31\uC5C5\uC740 \uC885\uB2E8 \uAC04 \uC554\uD638\uD654\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uAE30\uAE30\uC5D0\uC11C \uC7A0\uAE08\uC744 \uD574\uC81C\uD558\uB824\uBA74 \uACC4\uC815 \uBE44\uBC00\uBC88\uD638\uB97C \uC785\uB825\uD558\uC138\uC694.",
    "account.unlock_failed": "\uBE44\uBC00\uBC88\uD638\uAC00 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC544 \uBC31\uC5C5 \uC7A0\uAE08\uC744 \uD574\uC81C\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uBE44\uBC00\uBC88\uD638\uB97C \uBCC0\uACBD\uD588\uB2E4\uBA74 \uC774\uC804 \uBE44\uBC00\uBC88\uD638\uB97C \uC0AC\uC6A9\uD558\uC138\uC694.",
    "account.cloud_save_locked": "\uD074\uB77C\uC6B0\uB4DC \uBC31\uC5C5\uC774 \uC554\uD638\uD654\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC704\uC5D0\uC11C \uC7A0\uAE08\uC744 \uD574\uC81C\uD55C \uB4A4 \uBC31\uC5C5\uD558\uC138\uC694.",
