    "pk.t_ff.TC": "\uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uC2DC\uD53C\uC624\uB124\uC774\uD2B8 (TC) \uD615\uC131 \uBD84\uC728",
    "pk.t_ff.TE": "\uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uC5D0\uB09C\uD14C\uC774\uD2B8 (TE) \uD615\uC131 \uBD84\uC728",
