    "pk.t_gel.arm": "\uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uAC94 \uD314 \uC0DD\uCCB4\uC774\uC6A9\uB960",
    "pk.t_gel.thigh": "\uD14C\uC2A4\uD1A0\uC2A4\uD14C\uB860 \uAC94 \uD5C8\uBC85\uC9C0 \uC0DD\uCCB4\uC774\uC6A9\uB960",
