    "onboarding.privacy_local_desc": "\uBCF5\uC6A9\uACFC \uAC80\uC0AC \uAE30\uB85D\uC740 \uC774 \uBE0C\uB77C\uC6B0\uC800\uC5D0 \uC800\uC7A5\uB429\uB2C8\uB2E4. \uAE30\uBCF8\uC801\uC73C\uB85C \uC5B4\uB514\uB85C\uB3C4 \uC804\uC1A1\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "onboarding.privacy_cloud": "\uB85C\uADF8\uC778\uC740 \uC120\uD0DD\uC785\uB2C8\uB2E4",
    "onboarding.privacy_cloud_desc": "\uACC4\uC815\uC744 \uB9CC\uB4E4\uBA74 \uC554\uD638\uD654\uB41C \uD074\uB77C\uC6B0\uB4DC \uBC31\uC5C5\uACFC \uAE30\uAE30 \uAC04 \uB3D9\uAE30\uD654\uB97C \uC4F8 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC5C6\uC5B4\uB3C4 \uBAA8\uB4E0 \uAE30\uB2A5\uC744 \uC4F8 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "onboarding.privacy_medical": "\uC774\uAC83\uC740 \uC758\uD559\uC801 \uC870\uC5B8\uC774 \uC544\uB2D9\uB2C8\uB2E4",
    "onboarding.privacy_medical_desc": "\uBB34\uC5C7\uB3C4 \uC9C4\uB2E8\uD560 \uC218 \uC5C6\uACE0, \uBB34\uC5C7\uC744 \uC368\uC57C \uD560\uC9C0\uB3C4 \uC54C\uB824\uC904 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uCE58\uB8CC\uB294 \uC790\uACA9 \uC788\uB294 \uC758\uB8CC\uC778\uACFC \uC0C1\uC758\uD558\uC138\uC694.",
