    "advisory.e2.body": "Son \xF6stradiol dozun biraz y\xFCksek g\xF6r\xFCn\xFCyor. Art\u0131rmak s\xFCreci h\u0131zland\u0131rmaz, sadece p\u0131ht\u0131 riskini biraz art\u0131rabilir. L\xFCtfen endi\u015Felenme, bu uygulaman\u0131n tahmini yanl\u0131\u015F olabilir. Bir klinikte hormon kan testi yapt\u0131rmak rakamlar\u0131 kalibre etmene yard\u0131mc\u0131 olabilir; son dozunu da g\xF6zden ge\xE7irmekte fayda var.",
    "advisory.t.body": "Son testosteron dozun biraz y\xFCksek g\xF6r\xFCn\xFCyor. Y\xFCksek kalmas\u0131 genelde kan\u0131 biraz koyula\u015Ft\u0131rmaktan \xF6teye ge\xE7miyor. L\xFCtfen endi\u015Felenme, bu uygulaman\u0131n tahmini yanl\u0131\u015F olabilir. Bir klinikte hormon kan testi yapt\u0131rmak rakamlar\u0131 kalibre etmene yard\u0131mc\u0131 olabilir; son dozunu da g\xF6zden ge\xE7irmekte fayda var.",
    "advisory.cpa.body": "Son CPA dozun biraz y\xFCksek g\xF6r\xFCn\xFCyor. Art\u0131rmak testosteronu daha iyi bask\u0131lam\u0131yor, risk zamanla yava\u015F\xE7a art\u0131yor. L\xFCtfen endi\u015Felenme, bu uygulaman\u0131n tahmini yanl\u0131\u015F olabilir. Bir klinikte hormon kan testi yapt\u0131rmak rakamlar\u0131 kalibre etmene yard\u0131mc\u0131 olabilir; son dozunu da g\xF6zden ge\xE7irmekte fayda var.",
    "advisory.e2_cpa.body": "Son \xF6stradiol ve CPA dozlar\u0131n ikisi de biraz y\xFCksek g\xF6r\xFCn\xFCyor. \xD6stradiol daha \xE7ok p\u0131ht\u0131 riski ta\u015F\u0131rken, CPA'n\u0131n riski zamanla birikiyor. L\xFCtfen endi\u015Felenme, bu uygulaman\u0131n tahmini yanl\u0131\u015F olabilir. Bir klinikte hormon kan testi yapt\u0131rmak rakamlar\u0131 kalibre etmene yard\u0131mc\u0131 olabilir; son dozunu da g\xF6zden ge\xE7irmekte fayda var.",
    "advisory.calibrate.text": "Bu bir model tahmini.",
    "advisory.calibrate.cta": "Kalibre etmek i\xE7in kan tahlili ekle",
    "advisory.hormone_both_low.body": "Son \xF6stradiol ve testosteron tahlillerin ikisi de d\xFC\u015F\xFCk g\xF6r\xFCn\xFCyor. \u0130ki cinsiyet hormonunun ayn\u0131 anda d\xFC\u015F\xFCk olmas\u0131, zamanla kemik yo\u011Funlu\u011Funu, ruh halini ve ate\u015F basmas\u0131 gibi vazomotor belirtileri etkileyebilir. Bu, kan alma zamanlamas\u0131ndan da kaynaklanabilir; son dozlar\u0131nla birlikte bir doktorla konu\u015Fmakta fayda var.",
    "advisory.hormone_both_high.body": "Son \xF6stradiol ve testosteron tahlillerin ikisi de y\xFCksek g\xF6r\xFCn\xFCyor, al\u0131\u015F\u0131lmad\u0131k bir kombinasyon. Kan alma zamanlamas\u0131 ya da birim kar\u0131\u015F\u0131kl\u0131\u011F\u0131ndan kaynaklanabilir; sonu\xE7lar\u0131 bir doktorla teyit etmekte fayda var.",
