    "dose.guide.cpa_hint.rec": "\xD6nerilen g\xFCnl\xFCk doz: 10\u201312.5 mg",
    "dose.guide.cpa_hint.combo": "\xD6strojenle birle\u015Ftirildi\u011Finde 10 mg/g\xFCn testosteronu maksimum d\xFCzeyde bask\u0131lar",
    "dose.guide.cpa_hint.ultralow": "Ultra d\xFC\u015F\xFCk se\xE7enek: her 1\u20133 g\xFCnde 12.5 mg (\u2248 3.5 mg/g\xFCn e\u015Fde\u011Feri)",
    "inj.guide.title": "Kullan\u0131m ve Doz",
    "inj.guide.safety": "Meme kanseri riski y\xFCksek veya ciddi karaci\u011Fer yetmezli\u011Fi varsa KULLANMAYIN!",
    "inj.guide.route_methods": "Yollar: Kas i\xE7i enjeksiyon, Deri alt\u0131 enjeksiyon",
    "inj.guide.route_warn": "E\u011Fitimsizseniz enjeksiyon yapmay\u0131n!",
    "inj.guide.dosage_title": "Doz:",
    "inj.guide.dosage_ev": "\xD6stradiol Valerat: her 5\u20137 g\xFCnde 5 mg / her 1\u20132 haftada 10 mg",
    "inj.guide.dosage_ec": "\xD6stradiol Sipionat: her 7 g\xFCnde 5\u20136 mg / her 14 g\xFCnde 10\u201312 mg",
    "inj.guide.sim_link": "Enjekte Edilebilir E2 Sim\xFClat\xF6r\xFC (\u0130ngilizce)",
    "inj.guide.notes_title": "\xD6nlemler:",
    "inj.guide.note_1": "Cam kesiklerini / k\u0131r\u0131lmay\u0131 / \xE7\xF6zeltiye mikro cam par\xE7ac\u0131klar\u0131n\u0131n kar\u0131\u015Fmas\u0131n\u0131 \xF6nlemek i\xE7in ampulleri do\u011Fru a\xE7\u0131n.",
    "inj.guide.note_2": "Ayn\u0131 b\xF6lgeye tekrar tekrar enjeksiyon yapmay\u0131n.",
    "inj.guide.note_3": "Kan damarlar\u0131ndan ka\xE7\u0131n\u0131n. Emboli riski!",
    "inj.guide.note_4": "Sinirlerden ka\xE7\u0131n\u0131n. Kas i\xE7i enjeksiyonlar i\xE7in g\xFCvenli b\xF6lgelere enjekte edin.",
    "inj.guide.note_5": "\xC7\xF6zelti ya\u011F bazl\u0131 oldu\u011Fundan, \xE7ekmek i\xE7in 12 numara (pembe, 18G) i\u011Fne ve enjekte etmek i\xE7in 6 numara (mavi, 23G/25G) i\u011Fne kullan\u0131n.",
    "inj.guide.note_6": "H\u0131zl\u0131 i\u011Fne giri\u015Fi ve enjeksiyon i\xE7in taze i\u011Fne kullanmak a\u011Fr\u0131y\u0131 azaltmaya yard\u0131mc\u0131 olur.",
    "inj.guide.note_7": "Kendi kendine enjeksiyon i\xE7in vastus lateralis (d\u0131\u015F uylu\u011Fun orta k\u0131sm\u0131) veya deltoid (a\u015F\u0131 b\xF6lgesi) kullan\u0131n.",
    "inj.guide.note_8": "\u0130\u011Fneyi sokarken \u015Fiddetli a\u011Fr\u0131 hisseder veya \xF6nemli kan geri ak\u0131\u015F\u0131 g\xF6r\xFCrseniz hemen \xE7ekin, i\u011Fneyi de\u011Fi\u015Ftirin ve enjeksiyon b\xF6lgesini de\u011Fi\u015Ftirin.",
    "inj.guide.note_9": "Enjeksiyondan sonra normalden fazla kanama ya\u015Farsan\u0131z (duruyorsa) bu normaldir \u2014 panik yapmay\u0131n.",
    "inj.guide.source": "Kaynak: MtF.wiki",
