    "cal.desc.average": "Yaln\u0131zca genlik d\xFCzeltmesi: logaritmik uzayda en k\xFC\xE7\xFCk kareler ile tek bir ki\u015Fisel katsay\u0131 (\xF6l\xE7\xFClen \xF7 tahmin edilenin geometrik ortalamas\u0131). D\xFCzeyi ayarlar, e\u011Fri bi\xE7imini de\u011Fi\u015Ftirmez.",
    "cal.desc.adaptive": "Genlik ve klirensin birlikte uydurulmas\u0131: farmakokinetik, eliminasyon h\u0131z\u0131 \xE7arpanlar\u0131ndan olu\u015Fan bir \u0131zgarada yeniden sim\xFCle edilir ve log art\u0131klar\u0131n\u0131 en aza indiren katsay\u0131 ile yar\u0131 \xF6m\xFCr se\xE7ilir. Klirensi kayd\u0131rmak i\xE7in aral\u0131kl\u0131 3+ tahlil gerekir; aksi halde yaln\u0131zca genli\u011Fe iner.",
    "cal.recommended": "\xD6nerilen",
    "cal.off.pro.1": "Tamamen \u015Feffaf; tek bir ayk\u0131r\u0131 tahlilden etkilenmez",
    "cal.off.con.1": "\xD6l\xE7\xFClen de\u011Ferlere g\xF6re ki\u015Fiselle\u015Ftirme yok",
    "cal.average.pro.1": "T\xFCm tahlillerden tek bir sa\u011Flam katsay\u0131; ayk\u0131r\u0131 de\u011Ferlere dayan\u0131kl\u0131",
    "cal.average.pro.2": "Tek tahlille bile \xE7al\u0131\u015F\u0131r",
    "cal.average.con.1": "E\u011Friyi yaln\u0131zca yukar\u0131/a\u015Fa\u011F\u0131 kayd\u0131r\u0131r; bi\xE7imi veya yar\u0131 \xF6mr\xFC d\xFCzeltemez",
    "cal.adaptive.pro.1": "Genlik ve klirensi birlikte \xF6\u011Frenir; e\u011Fri bi\xE7imini d\xFCzeltir",
    "cal.adaptive.pro.2": "En d\xFC\u015F\xFCk uyum hatas\u0131; s\u0131n\u0131rl\u0131 oldu\u011Fu i\xE7in kontrolden \xE7\u0131kmaz",
    "cal.adaptive.con.1": "Yar\u0131 \xF6mr\xFC de\u011Fi\u015Ftirmek i\xE7in aral\u0131kl\u0131 3+ tahlil gerekir",
    "cal.ekf": "EKF",
    "cal.ou_kalman": "OU-Kalman",
    "cal.mipd": "Hybrid-MIPD",
    "cal.desc.ekf": "Geni\u015Fletilmi\u015F Kalman Filtresi. Tahlilleri zaman s\u0131ras\u0131yla i\u015Fler; ki\u015Fisel genlik ve klirens tahminini belirsizli\u011Fiyle birlikte s\xFCrekli g\xFCnceller. Kal\u0131c\u0131 bellek \u2014 her tahlil iz b\u0131rak\u0131r.",
    "cal.desc.ou_kalman": "Ornstein\u2013Uhlenbeck Kalman d\xFCzle\u015Ftirici. D\xFCzeltmeyi, kayan ve modele geri d\xF6nen bir d\xFCzey olarak ele al\u0131r: her tahlilin etkisi yakla\u015F\u0131k iki haftada modele s\xF6ner. Sabit bir katsay\u0131 yerine zamanla de\u011Fi\u015Fen bir d\xFCzeyi izler.",
    "cal.desc.mipd": "Modele dayal\u0131 hassas dozlama. Pop\xFClasyon \xF6nselinde genlik ve klirensin sa\u011Flam (Student-t) olabilirlikle MAP uydurumu: tahlil az oldu\u011Funda pop\xFClasyona \xE7ekilir ve tek bir ayk\u0131r\u0131 de\u011Fere ald\u0131rmaz.",
    "cal.ekf.pro.1": "Genlik ve klirensi \xF6\u011Frenir, her tahlille g\xFCncellenir",
    "cal.ekf.pro.2": "Kendi belirsizli\u011Fini izler; s\u0131n\u0131rl\u0131 oldu\u011Fu i\xE7in kontrolden \xE7\u0131kmaz",
    "cal.ekf.con.1": "Kal\u0131c\u0131 bellek \u2014 eski bir tahlil tahmini \xE7ekmeyi s\xFCrd\xFCr\xFCr",
    "cal.ou_kalman.pro.1": "Sabit katsay\u0131 de\u011Fil, zamanla kayan bir d\xFCzeyi izler",
    "cal.ou_kalman.pro.2": "Yeni tahliller daha a\u011F\u0131r basar; eskiler kendili\u011Finden solar",
    "cal.ou_kalman.con.1": "Yaln\u0131zca d\xFCzeyi d\xFCzeltir \u2014 e\u011Friyi veya yar\u0131 \xF6mr\xFC de\u011Fi\u015Ftirmez",
    "cal.mipd.pro.1": "Ayk\u0131r\u0131 de\u011Ferlere dayan\u0131kl\u0131; veri azken pop\xFClasyona yaslan\u0131r",
    "cal.mipd.pro.2": "Genlik ve klirensi \xF6\u011Frenir; tek tahlille \xE7al\u0131\u015F\u0131r",
    "cal.mipd.con.1": "Yar\u0131 \xF6mr\xFC de\u011Fi\u015Ftirmek i\xE7in aral\u0131kl\u0131 3+ tahlil gerekir",
    "cal.history": "Ge\xE7mi\u015Fe uygulama",
