    "cal.retrospective": "Geriye d\xF6n\xFCk",
    "cal.desc.forward": "Nedensel \u2014 her nokta yaln\u0131zca o ana kadarki tahlilleri kullan\u0131r; yeni tahlil eklemek ge\xE7mi\u015F tahminleri de\u011Fi\u015Ftirmez.",
    "cal.desc.retrospective": "D\xFCzle\u015Ftirilmi\u015F \u2014 t\xFCm tahliller ge\xE7mi\u015Fin tamam\u0131n\u0131 yeniden tahmin eder. Geriye d\xF6n\xFCk olarak daha do\u011Frudur; yeni bir tahlil eski tahminleri de\u011Fi\u015Ftirebilir.",
